/**
 * Turn-usage ring buffer helper used by App.tsx to maintain the
 * sliding window of recent turns fed into TokenPanel.
 *
 * Extracted from ../TokenPanel.tsx on 2026-04-23.
 */

import type { TurnUsage } from './types.js';

export const TURN_RING_SIZE = 20;

/**
 * Append `entry` to `ring` and trim from the front so the returned
 * array never exceeds TURN_RING_SIZE. Always returns a new array
 * (no mutation) so React state updates identify the change.
 */
export function pushTurnUsage(ring: TurnUsage[], entry: TurnUsage): TurnUsage[] {
  const next = [...ring, entry];
  return next.length > TURN_RING_SIZE
    ? next.slice(next.length - TURN_RING_SIZE)
    : next;
}

